import json, re, os

def parse_json_blocks(path):
    with open(path) as f:
        html = f.read()
    blocks = re.findall(r'<script type="application/json"[^>]*>(.*?)</script>', html, re.DOTALL)
    results = []
    for b in blocks:
        try:
            results.append(json.loads(b))
        except:
            pass
    return results

# Main repo page
blocks = parse_json_blocks('/root/.local/share/opencode/tool-output/tool_f5c92192c001kpbX1KAdm2tqHl')
print("Main repo blocks:", len(blocks))
for i, d in enumerate(blocks):
    # dump keys if dict
    if isinstance(d, dict):
        print(f"Block {i} keys: {list(d.keys())[:10]}")
        if 'payload' in d:
            p = d['payload']
            if isinstance(p, dict):
                if 'codeViewRepoRoute' in p:
                    print("  has codeViewRepoRoute")
                if 'overview' in p:
                    print("  has overview")
                if 'codeViewLayoutRoute' in p:
                    repo = p.get('codeViewLayoutRoute', {}).get('repo', {})
                    print("  repo keys:", list(repo.keys()))
                    print("  defaultBranch:", repo.get('defaultBranch'))
                    print("  createdAt:", repo.get('createdAt'))
                    print("  isFork:", repo.get('isFork'))
                    print("  isEmpty:", repo.get('isEmpty'))
                    # look for primaryLanguage
                    if 'primaryLanguage' in repo:
                        print("  primaryLanguage:", repo.get('primaryLanguage'))
                    # look for language in any sub key
                    def search(d, path=""):
                        if isinstance(d, dict):
                            for k, v in d.items():
                                if k.lower() in ('language', 'primarylanguage', 'programminglanguage', 'lang'):
                                    print(f"    found {path}.{k} = {v}")
                                if isinstance(v, (dict, list)):
                                    search(v, f"{path}.{k}")
                        elif isinstance(d, list):
                            for idx, item in enumerate(d):
                                search(item, f"{path}[{idx}]")
                    search(repo)

print("\n--- Commits page ---")
commits_blocks = parse_json_blocks('/root/.local/share/opencode/tool-output/tool_f5c92af1a001cgWOAszxfuikss')
print("Commits blocks:", len(commits_blocks))
for i, d in enumerate(commits_blocks):
    if isinstance(d, dict):
        print(f"Block {i} keys: {list(d.keys())[:10]}")
        if 'payload' in d:
            p = d['payload']
            if isinstance(p, dict):
                for k, v in p.items():
                    print(f"  payload key: {k}")
                if 'commitList' in p:
                    cl = p['commitList']
                    print("  commitList keys:", list(cl.keys()))
                    if 'commits' in cl:
                        print("  commits count:", len(cl['commits']))
                        if cl['commits']:
                            print("  first commit keys:", list(cl['commits'][0].keys()))
                            print("  first committedDate:", cl['commits'][0].get('committedDate'))
                            print("  first committedDate timestamp:", cl['commits'][0].get('committedDate'))
                            # also authorDate maybe
                    if 'pageInfo' in cl:
                        print("  pageInfo:", cl['pageInfo'])
                else:
                    # search for commits deeper
                    def search(d, path=""):
                        if isinstance(d, dict):
                            for k, v in d.items():
                                if k.lower() in ('commit', 'commits', 'committeddate', 'committeddate'):
                                    print(f"    found {path}.{k} = {str(v)[:200]}")
                                if isinstance(v, (dict, list)):
                                    search(v, f"{path}.{k}")
                        elif isinstance(d, list):
                            for idx, item in enumerate(d):
                                search(item, f"{path}[{idx}]")
                    search(p)

print("\n--- Issues page ---")
issues_blocks = parse_json_blocks('/root/.local/share/opencode/tool-output/tool_f5c92af18001Ok8u7qnttKjfzl')
print("Issues blocks:", len(issues_blocks))
for i, d in enumerate(issues_blocks):
    if isinstance(d, dict):
        print(f"Block {i} keys: {list(d.keys())[:10]}")
        if 'payload' in d:
            p = d['payload']
            if isinstance(p, dict):
                for k, v in p.items():
                    print(f"  payload key: {k}")
                # search for issue counts
                def search(d, path=""):
                    if isinstance(d, dict):
                        for k, v in d.items():
                            if k.lower() in ('openissuescount', 'totalcount', 'openissues', 'issuecount', 'count'):
                                print(f"    found {path}.{k} = {v}")
                            if isinstance(v, (dict, list)):
                                search(v, f"{path}.{k}")
                    elif isinstance(d, list):
                        for idx, item in enumerate(d):
                            search(item, f"{path}[{idx}]")
                search(p)

print("\n--- .github tree page ---")
